# ===========================================================================
# 50. LA GÉOMÉTRIE D'UN ENGRENAGE
# ===========================================================================

def geometrie_engrenage():
    p = [_txt(40, 26, "Tout part du module m — la taille d'une dent :", 13, TRAIT, "start", True)]
    cx, cy = 250, 190
    p.append(f"<circle cx='{cx}' cy='{cy}' r='120' fill='none' stroke='{TRAIT}' stroke-width='2'/>")
    p.append(f"<circle cx='{cx}' cy='{cy}' r='105' fill='none' stroke='{AXE}' stroke-width='2' stroke-dasharray='9 5'/>")
    p.append(f"<circle cx='{cx}' cy='{cy}' r='86' fill='none' stroke='{FIN}' stroke-width='1.4'/>")
    p.append(f"<circle cx='{cx}' cy='{cy}' r='26' fill='{FOND}' stroke='{TRAIT}' stroke-width='2'/>")
    # quelques dents
    import math as _m
    for k in range(18):
        a1 = _m.radians(k * 20 - 4)
        a2 = _m.radians(k * 20 + 4)
        x1, y1 = cx + 105 * _m.cos(a1), cy + 105 * _m.sin(a1)
        x2, y2 = cx + 120 * _m.cos(a1), cy + 120 * _m.sin(a1)
        x3, y3 = cx + 120 * _m.cos(a2), cy + 120 * _m.sin(a2)
        x4, y4 = cx + 105 * _m.cos(a2), cy + 105 * _m.sin(a2)
        p.append(f"<path d='M{x1:.0f},{y1:.0f} L{x2:.0f},{y2:.0f} L{x3:.0f},{y3:.0f} L{x4:.0f},{y4:.0f}' "
                 f"fill='#e2e8f0' stroke='{TRAIT}' stroke-width='1.4'/>")
    # cotes
    p.append(f"<line x1='{cx}' y1='{cy}' x2='{cx + 120}' y2='{cy}' stroke='{TRAIT}' stroke-width='1.2'/>")
    p.append(_txt(cx + 60, cy - 8, "da/2", 11, TRAIT, "middle", True))
    p.append(f"<line x1='{cx}' y1='{cy}' x2='{cx - 74}' y2='{cy - 74}' stroke='{AXE}' stroke-width='1.6'/>")
    p.append(_txt(cx - 60, cy - 52, "d/2", 11, AXE, "middle", True))
    p.append(_txt(cx, cy + 148, "d : diamètre primitif — le cercle qui « roule »", 11, AXE, "middle", True))

    p.append(f"<rect x='420' y='60' width='300' height='230' rx='8' fill='#ffffff' stroke='{ALESAGE}' stroke-width='2'/>")
    lignes = [("m", "le module, en mm — normalisé", TRAIT),
              ("Z", "le nombre de dents", TRAIT),
              ("d = m × Z", "diamètre primitif", AXE),
              ("da = d + 2m", "diamètre de tête", TRAIT),
              ("df = d − 2,5m", "diamètre de pied", TRAIT),
              ("p = π × m", "pas : distance entre 2 dents", FIN),
              ("a = m(Z1+Z2)/2", "entraxe des deux roues", ARBRE),
              ("h = 2,25 m", "hauteur totale de dent", FIN)]
    y = 92
    for f, sens, couleur in lignes:
        p.append(_txt(440, y, f, 12, couleur, "start", True))
        p.append(_txt(575, y, sens, 10, FIN))
        y += 26
    p.append(f"<rect x='40' y='320' width='680' height='66' fill='#f0fdf4' stroke='{OK}' rx='6'/>")
    p.append(_txt(56, 343, "Deux roues qui engrènent ont OBLIGATOIREMENT le même module.", 12, TRAIT, "start", True))
    p.append(_txt(56, 363, "Et il faut environ 17 dents minimum : en dessous, l'outil de taillage entame le pied", 12, FIN))
    p.append(_txt(56, 381, "de la dent et l'affaiblit — c'est l'interférence.", 12, FIN))
    return _svg("".join(p), 760, 400)


