def calcul_cordon():
    p = [_txt(40, 26, "La gorge « a » est la plus petite épaisseur du cordon — c'est elle qui résiste :",
              13, TRAIT, "start", True)]
    # deux toles en angle
    p.append(f"<rect x='110' y='90' width='40' height='170' fill='#cbd5e1' stroke='{TRAIT}' stroke-width='2'/>")
    p.append(f"<rect x='150' y='220' width='210' height='40' fill='#cbd5e1' stroke='{TRAIT}' stroke-width='2'/>")
    # cordon
    p.append(f"<path d='M150,160 L150,220 L215,220 Z' fill='{ARBRE}' opacity='0.45' stroke='{ARBRE}' stroke-width='2'/>")
    p.append(_txt(238, 200, "le cordon", 11, ARBRE, "start", True))
    # gorge a
    p.append(f"<line x1='150' y1='220' x2='190' y2='182' stroke='{ALERTE}' stroke-width='2.4'/>")
    p.append(_txt(200, 172, "a", 15, ALERTE, "start", True))
    p.append(_txt(214, 174, "= gorge", 11, ALERTE, "start"))
    # cote z
    p.append(f"<line x1='142' y1='160' x2='142' y2='220' stroke='{FIN}' stroke-width='1'/>")
    p.append(_txt(134, 194, "z", 11, FIN, "end", True))
    p.append(_txt(235, 292, "a ≈ 0,7 z", 12, TRAIT, "start", True))
    p.append(f"<rect x='400' y='75' width='320' height='195' rx='8' fill='#ffffff' stroke='{ALESAGE}' stroke-width='2'/>")
    p.append(_txt(560, 100, "Le calcul", 12, ALESAGE, "middle", True))
    p.append(_txt(418, 128, "Section résistante :  S = a × L", 12, TRAIT, "start", True))
    p.append(_txt(418, 152, "L = longueur utile du cordon", 10, FIN))
    p.append(_txt(418, 182, "Contrainte :  τ = F / (a × L)", 12, TRAIT, "start", True))
    p.append(_txt(418, 212, "Condition :  τ ≤ Rpg du métal", 12, OK, "start", True))
    p.append(_txt(418, 232, "le plus faible des deux assemblés", 10, FIN))
    p.append(_txt(418, 256, "Règle de choix :  a ≈ 0,7 × e mini", 11, ARBRE, "start", True))
    p.append(f"<rect x='40' y='310' width='680' height='68' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, 333, "Un cordon plus gros ne rend pas l'assemblage plus solide au-delà de a = 0,7 e :", 12, TRAIT, "start", True))
    p.append(_txt(56, 353, "c'est la tôle qui cède avant. On gaspille du métal d'apport, du temps, et on déforme", 12, FIN))
    p.append(_txt(56, 371, "davantage la pièce. Trop souder est une faute, pas une précaution.", 12, ALERTE, "start", True))
    return _svg("".join(p), 760, 395)


