# 63. COMPARER LES SECTIONS À MASSE ÉGALE
# ===========================================================================

def sections_comparees():
    p = [_txt(40, 26, "Quatre sections de MÊME AIRE (1 200 mm²) — mais pas du tout la même résistance :",
              12, TRAIT, "start", True)]
    cases = [
        (55, "Carré 35×35", "I = 122 500", "1,0", FIN,
         [("rect", 40, 40)]),
        (230, "Rect. 20×60", "I = 360 000", "2,9", ALESAGE,
         [("rect", 24, 72)]),
        (405, "Tube Ø60/Ø46", "I = 460 000", "3,8", OK,
         [("tube", 62, 47)]),
        (580, "Profil I", "I = 780 000", "6,4", ARBRE,
         [("i", 0, 0)]),
    ]
    for x0, nom, inertie, rapport, couleur, forme in cases:
        p.append(f"<rect x='{x0}' y='55' width='150' height='250' rx='8' fill='#ffffff' stroke='{couleur}' stroke-width='2'/>")
        p.append(_txt(x0 + 75, 79, nom, 11, couleur, "middle", True))
        cx, cy = x0 + 75, 155
        kind = forme[0][0]
        if kind == "rect":
            w, h = forme[0][1], forme[0][2]
            p.append(f"<rect x='{cx - w / 2}' y='{cy - h / 2}' width='{w}' height='{h}' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='2'/>")
        elif kind == "tube":
            de, di = forme[0][1], forme[0][2]
            p.append(f"<circle cx='{cx}' cy='{cy}' r='{de / 2}' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='2'/>")
            p.append(f"<circle cx='{cx}' cy='{cy}' r='{di / 2}' fill='{FOND}' stroke='{TRAIT}' stroke-width='2'/>")
        else:
            p.append(f"<rect x='{cx - 32}' y='{cy - 40}' width='64' height='11' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='2'/>")
            p.append(f"<rect x='{cx - 6}' y='{cy - 29}' width='12' height='58' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='2'/>")
            p.append(f"<rect x='{cx - 32}' y='{cy + 29}' width='64' height='11' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='2'/>")
        p.append(f"<line x1='{cx - 45}' y1='{cy}' x2='{cx + 45}' y2='{cy}' stroke='{AXE}' stroke-width='1.2' stroke-dasharray='5 4'/>")
        p.append(_txt(cx, 232, inertie, 11, TRAIT, "middle", True))
        p.append(_txt(cx, 250, "mm⁴", 9, FIN, "middle"))
        p.append(f"<rect x='{x0 + 30}' y='266' width='90' height='26' rx='5' fill='{couleur}' opacity='0.2'/>")
        p.append(_txt(cx, 284, "× " + rapport, 13, couleur, "middle", True))
    p.append(f"<rect x='40' y='320' width='680' height='68' fill='#f0fdf4' stroke='{OK}' rx='6'/>")
    p.append(_txt(56, 343, "Même quantité de matière, même prix au kilo — et 6,4 fois plus de résistance.",
                  12, TRAIT, "start", True))
    p.append(_txt(56, 363, "La règle unique : ÉLOIGNER LA MATIÈRE DE L'AXE NEUTRE. Le profil I pousse cette", 12, FIN))
    p.append(_txt(56, 381, "logique à son terme — c'est pour cela qu'il existe.", 12, FIN))
    return _svg("".join(p), 760, 405)


