    for nom, val in crit:
        p.append(_txt(488, y, nom, 11, TRAIT))
        p.append(_txt(700, y, val, 11, ALESAGE, "end", True))
        y += 26
    p.append(f"<rect x='40' y='240' width='680' height='118' fill='#eff6ff' stroke='{ALESAGE}' rx='6'/>")
    p.append(_txt(56, 264, "Les deux vérifications sont INDÉPENDANTES :", 12, TRAIT, "start", True))
    p.append(_txt(56, 290, "RÉSISTANCE — σ = Mf / (I/v) ≤ Rpe", 11, OK, "start", True))
