def lire_table_iso():
    p = [_txt(40, 24, "Ø30 g6 — les quatre lectures à faire, dans l'ordre :", 13, TRAIT, "start", True)]
    # extrait de table
    p.append(f"<rect x='55' y='55' width='330' height='150' fill='#ffffff' stroke='{TRAIT}' stroke-width='1.6'/>")
    p.append(f"<rect x='55' y='55' width='330' height='28' fill='{ALESAGE}' opacity='0.15'/>")
    entetes = ["au-dessus de", "jusqu'à", "IT6", "IT7"]
    xs = [70, 150, 235, 305]
    for x, e in zip(xs, entetes):
        p.append(_txt(x, 74, e, 10, TRAIT, "start", True))
    lignes = [("10", "18", "11", "18"), ("18", "30", "13", "21"), ("30", "50", "16", "25")]
    y = 104
    for i, (a, b, it6, it7) in enumerate(lignes):
        if i == 1:
            p.append(f"<rect x='56' y='{y - 18}' width='328' height='30' fill='{ARBRE}' opacity='0.18'/>")
        for x, v in zip(xs, (a, b, it6, it7)):
            gras = i == 1
            p.append(_txt(x, y, v, 11, TRAIT if not gras else ARBRE, "start", gras))
        y += 34
    p.append(_txt(220, 226, "Ø30 est dans « au-dessus de 18, jusqu'à 30 »", 10, ARBRE, "middle", True))
    # etapes
    p.append(f"<rect x='410' y='55' width='310' height='190' rx='8' fill='#ffffff' stroke='{ALESAGE}' stroke-width='2'/>")
    etapes = [("1", "trouver la LIGNE du diamètre", "30 est dans la plage 18 à 30 → 2e ligne"),
              ("2", "lire l'IT dans la colonne du grade", "IT6 = 13 µm = 0,013 mm"),
              ("3", "lire l'écart de la LETTRE", "g : es = −7 µm"),
              ("4", "en déduire l'autre écart", "ei = es − IT = −20 µm")]
    y = 88
    for num, titre, detail in etapes:
        p.append(f"<circle cx='432' cy='{y - 4}' r='11' fill='{ALESAGE}'/>")
        p.append(_txt(432, y, num, 11, "#ffffff", "middle", True))
        p.append(_txt(452, y - 2, titre, 11, TRAIT, "start", True))
        p.append(_txt(452, y + 14, detail, 10, ARBRE))
        y += 44
    p.append(f"<rect x='40' y='265' width='680' height='90' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, 288, "LE PIÈGE : la table est en MICROMÈTRES, le plan en MILLIMÈTRES.", 12, TRAIT, "start", True))
    p.append(_txt(56, 310, "13 µm = 0,013 mm — et non 0,13. Une erreur de facteur 10 fait accepter une pièce", 12, FIN))
    p.append(_txt(56, 328, "dix fois hors tolérance, ou refuser toute une série de pièces bonnes.", 12, FIN))
    p.append(_txt(56, 350, "Résultat pour Ø30 g6 : de 29,980 à 29,993.", 12, OK, "start", True))
    return _svg("".join(p), 760, 375)


